import {
	Accessor,
	Component,
	createContext,
	createEffect,
	createMemo,
	createSignal,
	on,
	onMount,
	ParentComponent,
	Setter,
	useContext,
} from "solid-js";

import { TabContext, TabContextProvider, TabProps } from "#core/ui-next/components/tab.jsx";

export enum ScreenFlowStepType {
	Normal,
	/** Only 1 screen in a flow may be marked with hub */
	Hub,
	/** Only 1 screen in a flow may be marked with start */
	Start,
}

export interface ScreenFlowScreen {
	/** The name of tab that is active with this step */
	name: string;
	/** The name of the step this group belongs to */
	step?: string;
	/** CLOSE and START trigger onClose and onStart respectively, otherwise this is a screen name */
	next?: string;
	/** CLOSE and START trigger onClose and onStart respectively, otherwise this is a screen name */
	prev?: string;
	/** Is this screen the hub or start screen? */
	type?: ScreenFlowStepType;
}

export class ScreenFlowContextProvider extends TabContextProvider {
	private screens: ScreenFlowScreen[] = [];

	private onClose: ((screenName: string) => void) | undefined;
	private onStart: ((screenName: string) => void) | undefined;

	private _currentScreen: Accessor<ScreenFlowScreen | undefined>;

	private _startScreen: ScreenFlowScreen;
	private _isStartActive: Accessor<boolean>;

	private _hubScreen: ScreenFlowScreen | undefined;
	private _wasHubVisited: Accessor<boolean>;
	private _setWasHubVisited: Setter<boolean>;
	private _isHubActive: Accessor<boolean>;

	private _currentStep: Accessor<number>;
	private _numSteps: Accessor<number>;

	public get isStartActive(): Accessor<boolean> {
		return this._isStartActive;
	}

	public get isHubActive(): Accessor<boolean> {
		return this._isHubActive;
	}

	public get wasHubVisited(): Accessor<boolean> {
		return this._wasHubVisited;
	}

	public get currentStep(): Accessor<number> {
		return this._currentStep;
	}

	public get numSteps(): Accessor<number> {
		return this._numSteps;
	}

	constructor(
		screens: ScreenFlowScreen[],
		onClose?: (screenName: string) => void,
		onStart?: (screenName: string) => void,
	) {
		super();

		const steps: string[] = [];

		for (const screen of screens) {
			const step = screen.step;
			if (step && step.length > 0 && !steps.some((s) => s == step)) {
				steps.push(step);
			}
		}

		this.screens = screens;
		this.onClose = onClose;
		this.onStart = onStart;

		this._currentScreen = createMemo(() => this.screens.find((s) => s.name == this.active()?.name));

		this._startScreen = screens.find((s) => s.type == ScreenFlowStepType.Start) ?? screens[0];
		this._isStartActive = createMemo(() => this.active()?.name == this._startScreen?.name);

		this._hubScreen = screens.find((s) => s.type == ScreenFlowStepType.Hub);
		const [wasHubVisited, setWasHubisited] = createSignal(
			!!this._hubScreen?.name && this._startScreen.name == this._hubScreen?.name,
		);
		this._wasHubVisited = wasHubVisited;
		this._setWasHubVisited = setWasHubisited;
		this._isHubActive = createMemo(() => !!this._hubScreen?.name && this.active()?.name == this._hubScreen?.name);

		this._currentStep = createMemo(() => steps.findIndex((s) => s == this._currentScreen()?.step) + 1);
		this._numSteps = createMemo(() => steps.length);

		createEffect(
			on(
				() => this.active(),
				() => this._setWasHubVisited((wasVisited) => wasVisited || this.isHubActive()),
			),
		);
	}

	public activatePrev() {
		const prev = this._currentScreen()?.prev;
		if (this._wasHubVisited() && !this.isHubActive()) {
			return this.activate(this._hubScreen?.name ?? "");
		} else if (this.isStartActive() && !this._wasHubVisited()) {
			this.close();
		} else if (prev) {
			if (prev == "START") {
				this.start();
			} else if (prev == "CLOSE") {
				this.close();
			} else {
				return this.activate(prev);
			}
		} else {
			const index = this.screens.findIndex((s) => s.name == this._currentScreen()?.name);
			if (index >= 0) {
				const prevIndex = index - 1;
				if (index < 0) {
					this.close();
				} else {
					return this.activate(this.screens[prevIndex].name);
				}
			}
		}

		return true;
	}

	public activateNext() {
		const next = this._currentScreen()?.next;
		if (this._wasHubVisited() && !this.isHubActive()) {
			return this.activate(this._hubScreen?.name ?? "");
		} else if (this.isHubActive()) {
			this.start();
		} else if (next) {
			if (next == "START") {
				this.start();
			} else if (next == "CLOSE") {
				this.close();
			} else {
				return this.activate(next);
			}
		} else {
			const index = this.screens.findIndex((s) => s.name == this._currentScreen()?.name);
			if (index >= 0) {
				const nextIndex = index + 1;
				if (index >= this.screens.length) {
					this.start();
				} else {
					return this.activate(this.screens[nextIndex].name);
				}
			}
		}

		return true;
	}

	public clearHub() {
		this._setWasHubVisited(false);
	}

	public close() {
		this.onClose?.(this.active()?.name ?? this._startScreen.name);
	}

	public start() {
		this.onStart?.(this.active()?.name ?? this._startScreen.name);
	}
}

export const ScreenFlowContext = createContext<ScreenFlowContextProvider>();

export function useScreenFlowContext() {
	const context = useContext(ScreenFlowContext);

	if (!context) {
		throw new Error("");
	}

	return context;
}

export const ScreenFlowStepCount: Component = () => {
	const context = useScreenFlowContext();

	return (
		<div
			class="flex flex-row text-base ml-38 mt-8"
			style={{ color: "white" }}
		>
			STEP&nbsp;{context.currentStep()}&nbsp;of&nbsp;{context.numSteps()}
		</div>
	);
};

export interface ScreenFlowTabProps extends TabProps {
	screens: ScreenFlowScreen[];
	onClose?: (screenName: string) => void;
	onStart?: (screenName: string) => void;
	contextRef?: (context: ScreenFlowContextProvider) => void;
}

export const ScreenFlowTab: ParentComponent<ScreenFlowTabProps> = (props) => {
	// eslint-disable-next-line solid/reactivity
	const contextProvider = new ScreenFlowContextProvider(props.screens, props.onClose, props.onStart);

	createEffect(() => {
		props.onTabChanged?.(contextProvider.active());
	});

	createEffect(() => {
		if (props.defaultTab) {
			contextProvider.setDefaultTab(props.defaultTab);
		}
	});

	onMount(() => {
		if (props.contextRef) {
			props.contextRef(contextProvider);
		}
	});

	return (
		<div
			{...props}
			ref={props.ref}
			class={props.class ?? "flex flex-row"}
			data-name="Tab"
		>
			<TabContext.Provider value={contextProvider}>
				<ScreenFlowContext.Provider value={contextProvider}>{props.children}</ScreenFlowContext.Provider>
			</TabContext.Provider>
		</div>
	);
};
